const text = $json.content?.parts?.[0]?.text;

if (!text) {
  return [];
}

let parsed;

try {
  parsed = JSON.parse(text);
} catch (error) {
  return [];
}

if (!Array.isArray(parsed.contacts)) {
  return [];
}


function formatField(val) {
  if (val === null || val === undefined) return "Missing";
  const str = String(val).trim();
  return str.length > 0 ? str : "Missing";
}

function validateContact(email, phone) {
  const isEmailValid = email && email !== "Missing" && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  const isPhoneValid = phone && phone !== "Missing" && phone.replace(/\D/g, "").length >= 7;

  if (isEmailValid && isPhoneValid) return "Valid";
  if (!isEmailValid && !isPhoneValid) return "Invalid Email & Phone";
  if (!isEmailValid) return "Invalid Email";
  return "Invalid Phone";
}

function scoreLead(contact) {
  let score = 0;
  const reasons = [];

  const rawTitle = (contact.designation || contact.Designation || "").toLowerCase().trim();
  const rawCompany = (contact.company || contact.Company || "").trim();
  const rawEmail = (contact.email || contact.Email || "").toLowerCase().trim();
  const rawPhone = (contact.phone || contact.Phone || "").trim();
  const rawLinkedin = (contact.linkedin_url || contact.LinkedIn || "").trim();
  const rawIndustry = (contact.sector_industry || contact["Sector/Industry"] || "").toLowerCase().trim();
  const rawAddress = (contact.address || contact.Address || contact.city || "").trim();

  // 0. AI Competitor Conflict Check (Priority Override)
  const isEducationalOrTrust = /college|university|institution|institute|school|trust|academy|sns/i.test(rawCompany);
  const aiRegex = /\b(ai|artificial intelligence|generative ai|genai|llm|machine learning|deep learning|agentic ai)\b/i;
  const isAICompetitor = (aiRegex.test(rawIndustry) || aiRegex.test(rawCompany)) && !isEducationalOrTrust;

  if (isAICompetitor) {
    const compScore = 15;
    const tier = "Cold";
    const tierLabel = "Low Priority";
    const companyDisplay = rawCompany || "AI Vendor";
    const titleDisplay = contact.designation || contact.Designation || "Contact";
    const channels = [];
    if (rawPhone && rawPhone !== "Missing") channels.push("Phone: " + rawPhone);
    if (rawEmail && rawEmail !== "Missing") channels.push("Email: " + rawEmail);
    const channelStr = channels.length > 0 ? channels.join(", ") : "Official channels";

    const salesSummary = `[${tierLabel} - Score: ${compScore}/100] Profile: ${titleDisplay} at ${companyDisplay} [Sector: AI Solutions / Direct Competitor] | Verified Channels: ${channelStr} | Action: Direct AI industry competitor overlap. Deprioritized for sales outreach to avoid market conflict.`;

    return {
      score: compScore,
      tier,
      rationale: "Direct AI company overlap / competitor clash; low commercial suitability for sales pursuit",
      salesSummary
    };
  }

  // 1. Apex Leadership & Decision-Maker Authority (0-40 pts)
  const isApexLeader = /trustee|chairman|chairperson|correspondent|director|chancellor|principal|dean|president|founder|co-founder|chief|ceo|cto|cfo|coo|cro|owner|partner|secretary/i.test(rawTitle);

  if (isApexLeader) {
    score += 40;
    reasons.push("Apex institutional leadership / executive decision maker");
  } else if (/vp|vice president|head of|head|provost|controller/i.test(rawTitle)) {
    score += 35;
    reasons.push("Senior executive / department head");
  } else if (/manager|lead|supervisor|coordinator|hod|head of department/i.test(rawTitle)) {
    score += 25;
    reasons.push("Departmental management role");
  } else if (/professor|associate professor|assistant professor|specialist|consultant|analyst|engineer|architect|scientist|lecturer/i.test(rawTitle)) {
    score += 20;
    reasons.push("Academic faculty / domain specialist");
  } else if (rawTitle) {
    score += 15;
    reasons.push("Professional staff role");
  } else {
    score += 5;
    reasons.push("Designation not specified");
  }

  // 2. Sector & Institutional Value (0-30 pts)
  const isTargetSector = /education|college|university|institution|institute|trust|academy|foundation|academic|school|software|saas|it|cloud|cybersecurity|data|engineering|healthcare|pharma|finance|banking/i.test(rawIndustry) ||
    /sns|college|institution|institute|university|trust|foundation|academy|school|technologies|systems|labs|industries|corp|group/i.test(rawCompany.toLowerCase());

  if (isTargetSector) {
    score += 30;
    reasons.push("Institutional / High-priority sector");
  } else if (rawCompany || rawIndustry) {
    score += 20;
    reasons.push("Standard commercial organization");
  } else {
    score += 5;
  }

  // 3. Reachability & Verified Contact Details (0-30 pts)
  let reachScore = 0;
  const isPersonalEmail = /gmail|yahoo|hotmail|outlook|icloud|aol/i.test(rawEmail);

  if (rawEmail && rawEmail !== "Missing" && !isPersonalEmail) {
    reachScore += 15;
  } else if (rawEmail && rawEmail !== "Missing") {
    reachScore += 8;
  }

  if (rawPhone && rawPhone !== "Missing" && rawPhone.replace(/\D/g, "").length >= 7) {
    reachScore += 10;
  }

  if (rawLinkedin && rawLinkedin !== "Missing" && rawLinkedin.includes("linkedin")) {
    reachScore += 5;
  } else if (rawAddress && rawAddress !== "Missing") {
    reachScore += 5;
  }

  score += reachScore;
  reasons.push(reachScore >= 20 ? "High reachability" : "Verified contact channels");

  if (isApexLeader) {
    score = Math.max(score, 85);
  }

  score = Math.min(100, Math.max(0, score));

  let tier = "Cold";
  if (score >= 70) {
    tier = "Hot";
  } else if (score >= 40) {
    tier = "Warm";
  }

  let tierLabel = "Low Priority";
  if (tier === "Hot") tierLabel = "High Priority";
  else if (tier === "Warm") tierLabel = "Medium Priority";

  const companyDisplay = rawCompany || "SNS Institutions";
  const titleDisplay = contact.designation || contact.Designation || "Leadership";

  let action = "";
  if (isApexLeader) {
    action = "Apex institutional leadership. Prepare executive briefing for strategic partnerships and high-level institutional collaboration.";
  } else if (tier === "Hot") {
    action = "Initiate direct executive correspondence via official communication channels.";
  } else if (tier === "Warm") {
    action = "Send institutional introduction and case study; request connection with designated department lead.";
  } else {
    action = "Maintain on institutional communication list; low priority for manual direct outreach.";
  }

  const channels = [];
  if (rawPhone && rawPhone !== "Missing") channels.push("Phone: " + rawPhone);
  if (rawEmail && rawEmail !== "Missing") channels.push((isPersonalEmail ? "Personal Email: " : "Official Email: ") + rawEmail);
  if (rawAddress && rawAddress !== "Missing") channels.push("Location: " + rawAddress);
  const channelStr = channels.length > 0 ? channels.join(", ") : "Official institutional channels";

  const salesSummary = `[${tierLabel} - Score: ${score}/100] Profile: ${titleDisplay} at ${companyDisplay} | Verified Channels: ${channelStr} | Action: ${action}`;

  return {
    score,
    tier,
    rationale: reasons.join("; "),
    salesSummary
  };
}


